package cd.go.authentication.ldap.model;

import com.google.gson.JsonObject;
import com.google.gson.annotations.Expose;
import com.google.gson.annotations.SerializedName;
import com.google.gson.reflect.TypeToken;

import java.lang.reflect.Type;
import java.util.List;

import static cd.go.authentication.ldap.utils.Util.GSON;

public class AuthConfig {
    @Expose
    @SerializedName("id")
    private String id;

    @Expose
    @SerializedName("configuration")
    private LdapConfiguration configuration;

    public AuthConfig() {
    }

    public AuthConfig(String id, LdapConfiguration ldapConfiguration) {
        this.id = id;
        configuration = ldapConfiguration;
    }

    public String getId() {
        return id;
    }

    public LdapConfiguration getConfiguration() {
        return configuration;
    }

    public static List<AuthConfig> fromJSONList(String requestBody) {
        JsonObject jsonObject = GSON.fromJson(requestBody, JsonObject.class);
        Type type = new TypeToken<List<AuthConfig>>() {
        }.getType();
        return GSON.fromJson(jsonObject.get("auth_configs").toString(), type);
    }

    public static AuthConfig fromJSON(String json) {
        return GSON.fromJson(json, AuthConfig.class);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        AuthConfig that = (AuthConfig) o;

        if (id != null ? !id.equals(that.id) : that.id != null) return false;
        return configuration != null ? configuration.equals(that.configuration) : that.configuration == null;
    }

    @Override
    public int hashCode() {
        int result = id != null ? id.hashCode() : 0;
        result = 31 * result + (configuration != null ? configuration.hashCode() : 0);
        return result;
    }
}
